103	/// A point with `f64` coordinates — the C++ `Clipper2Lib::PointD`.
104	#[derive(Clone, Copy, Debug, Default, PartialEq)]
105	pub struct PointD {
106	    pub x: f64,
107	    pub y: f64,
108	}
109	
110	impl PointD {
111	    /// Constructs a point, matching the C++ `PointD(x, y)` constructor.
112	    #[inline]
