114	        Self { x, y }
115	    }
116	
117	    /// Rounds to the nearest [`Point64`], half away from zero.
118	    #[inline]
119	    pub fn to_point64(self) -> Point64 {
120	        Point64::from_rounded(self.x, self.y)
121	    }
122	}
123	
124	impl From<(f64, f64)> for PointD {
125	    #[inline]
126	    fn from((x, y): (f64, f64)) -> Self {
127	        Self::new(x, y)
128	    }
129	}
130	
131	impl From<Point64> for PointD {
132	    #[inline]
133	    fn from(p: Point64) -> Self {
134	        p.to_point_d()
135	    }
136	}
