138	#[cfg(test)]
139	mod tests {
140	    use super::*;
141	
142	    #[test]
143	    fn new_stores_coordinates_verbatim() {
144	        let p = Point64::new(100, -100);
145	        assert_eq!((p.x, p.y), (100, -100));
146	        assert_eq!(Point64::default(), Point64::ORIGIN);
147	    }
148	
149	    #[test]
150	    fn equality_is_componentwise() {
151	        assert_eq!(Point64::new(0, 0), Point64::from((0, 0)));
152	        assert_ne!(Point64::new(0, 1), Point64::new(1, 0));
153	    }
154	
155	    #[test]
156	    fn arithmetic_matches_cpp_operators() {
157	        let a = Point64::new(3, 4);
158	        let b = Point64::new(10, 20);
159	        assert_eq!(a + b, Point64::new(13, 24));
160	        assert_eq!(b - a, Point64::new(7, 16));
161	        assert_eq!(-a, Point64::new(-3, -4));
162	        assert_eq!(a.translate(-3, -4), Point64::ORIGIN);
163	    }
164	
165	    #[test]
166	    fn rounding_is_half_away_from_zero() {
167	        assert_eq!(Point64::from_rounded(0.5, -0.5), Point64::new(1, -1));
168	        assert_eq!(Point64::from_rounded(1.4, -1.6), Point64::new(1, -2));
169	        assert_eq!(PointD::new(2.5, 3.5).to_point64(), Point64::new(3, 4));
170	    }
171	
172	    #[test]
173	    fn conversions_round_trip() {
174	        let p = Point64::new(100, 100);
175	        assert_eq!(PointD::from(p).to_point64(), p);
176	        assert_eq!(<(i64, i64)>::from(p), (100, 100));
177	    }
178	
179	    #[test]
180	    fn display_is_comma_separated() {
181	        assert_eq!(Point64::new(100, 0).to_string(), "100,0");
182	    }
183	}
