388	        let path = test1_path();
389	        assert_eq!(path[0], Point64::new(0, 0));
390	        assert_eq!(path[3], Point64::new(0, 100));
391	        assert_eq!(path.points().last().copied(), Some(Point64::new(0, 100)));
