424	        // A 100x100 square, wound clockwise in screen coordinates.
425	        assert_eq!(test1_path().signed_area2(), 20_000);
426	        assert_eq!(test1_path().area(), 10_000.0);
427	        // Fewer than three points cannot enclose area.
428	        assert_eq!(path64![(0, 0), (1, 1)].area(), 0.0);
