50	    /// Horizontal extent — the C++ `Width()`.
51	    #[inline]
52	    pub fn width(&self) -> i64 {
53	        self.right - self.left
54	    }
55	
56	    /// Vertical extent — the C++ `Height()`.
57	    #[inline]
58	    pub fn height(&self) -> i64 {
59	        self.bottom - self.top
60	    }
