74	    /// Whether `p` lies inside or on the boundary — the C++ `Contains()`.
75	    #[inline]
76	    pub fn contains(&self, p: Point64) -> bool {
77	        p.x >= self.left && p.x <= self.right && p.y >= self.top && p.y <= self.bottom
78	    }
